// Spec 010 T041: the "More basemaps…" gallery. DATA generated by
// scripts/basemap-catalog.mjs from maplibre-gl-basemap-control (MIT, © 2026
// Qiusheng Wu); this module searches it and turns an entry (with its API key,
// when it needs one) into a BasemapCatalogEntry the map can load.
import gallery from './basemapGallery.json'
import type { BasemapCatalogEntry } from './basemapCatalog.js'

export interface GalleryBasemap {
  /** The package id, prefixed `g-` (never clashes with a featured id). */
  id: string
  name: string
  provider: string
  providerName: string
  kind: 'raster' | 'vector'
  category: string
  description: string
  /** Sanitized: plain text and `<a href="https://…">` links only. */
  attribution: string
  /** Vector: the style URL (may hold `{api-key}`). */
  url?: string
  /** Raster: tile URL templates (may hold `{api-key}`). */
  tiles?: string[]
  tileSize?: number
  maxzoom?: number
  /** Raster tiles numbered bottom-up. */
  scheme?: 'xyz' | 'tms'
  key: 'none' | 'optional' | 'required'
  tags: string[]
}

export const GALLERY: GalleryBasemap[] = gallery.basemaps as GalleryBasemap[]
export const GALLERY_SOURCE: string = gallery.source

/** Where to get a key, per keyed provider. */
export const KEY_SIGNUP: Record<string, string> = {
  maptiler: 'https://cloud.maptiler.com/account/keys/',
  stadia: 'https://client.stadiamaps.com/signup/',
  protomaps: 'https://protomaps.com/account',
  carto: 'https://carto.com/',
}

/** The secret's name for a provider's key (HostAdapter.getSecret). */
export function basemapKeyName(provider: string): string {
  return `basemapKey.${provider}`
}

export function galleryCategories(): string[] {
  return [...new Set(GALLERY.map((g) => g.category))].sort()
}

export function galleryProviders(): Array<{ id: string; name: string }> {
  const seen = new Map<string, string>()
  for (const g of GALLERY) seen.set(g.provider, g.providerName)
  return [...seen].map(([id, name]) => ({ id, name })).sort((a, b) => a.name.localeCompare(b.name))
}

export function findGalleryBasemap(id: string): GalleryBasemap | undefined {
  return GALLERY.find((g) => g.id === id)
}

/** Every word of `q` must appear in the name, provider, category, description or tags (any case). */
export function searchGallery(
  q: string,
  filters: { category?: string | null; provider?: string | null; keylessOnly?: boolean } = {},
  list: readonly GalleryBasemap[] = GALLERY
): GalleryBasemap[] {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean)
  return list.filter((g) => {
    if (filters.category && g.category !== filters.category) return false
    if (filters.provider && g.provider !== filters.provider) return false
    if (filters.keylessOnly && g.key === 'required') return false
    if (!words.length) return true
    const text = [g.name, g.providerName, g.category, g.description, ...g.tags].join(' ').toLowerCase()
    return words.every((w) => text.includes(w))
  })
}

const KEY = '{api-key}'

/** Drops a `key={api-key}` query parameter (any `…key` name) and the separator it leaves. */
function withoutKeyParam(url: string): string {
  return url.replace(/([?&])[\w-]*key=\{api-key\}(&?)/i, (_m, sep: string, amp: string) => (amp ? sep : '')).replace(/[?&]$/, '')
}

/**
 * The entry's URLs with the key in place. A key-optional entry without a key
 * drops its key parameter; a key-required one says it needs one.
 */
export function applyKey(g: GalleryBasemap, key: string | null): { url?: string; tiles?: string[] } | { needsKey: true } {
  const k = key?.trim() || null
  if (g.key === 'required' && !k) return { needsKey: true }
  const fill = (u: string): string => (k ? u.split(KEY).join(encodeURIComponent(k)) : withoutKeyParam(u))
  return g.url !== undefined ? { url: fill(g.url) } : { tiles: (g.tiles ?? []).map(fill) }
}

/** A gallery entry, its URLs resolved (applyKey), as the map's catalog entry; `keyed` when a key was applied. */
export function toCatalogEntry(g: GalleryBasemap, resolved: { url?: string; tiles?: string[] }, keyed = false): BasemapCatalogEntry {
  return {
    id: g.id,
    name: g.name,
    type: g.kind,
    url: resolved.url ?? resolved.tiles?.[0] ?? '',
    ...(resolved.tiles ? { tiles: resolved.tiles } : {}),
    attribution: g.attribution,
    requiresKey: g.key === 'required',
    region: 'global',
    preview: null,
    provider: g.provider,
    providerName: g.providerName,
    ...(keyed ? { keyed: true } : {}),
    ...(g.maxzoom !== undefined ? { maxzoom: g.maxzoom } : {}),
    ...(g.tileSize !== undefined ? { tileSize: g.tileSize } : {}),
    ...(g.scheme !== undefined ? { scheme: g.scheme } : {}),
  }
}
